package gg.grounds.resourcepacks.product

import gg.grounds.resourcepack.api.PackEntry
import gg.grounds.resourcepack.api.PackPath
import gg.grounds.resourcepack.api.VanillaPathClaim
import java.security.MessageDigest

/**
 * Fonts and `gui` shaders for the plugin-lobby dialog-body menus (`/settings`).
 *
 * Generated by plugin-lobby's `MenuPackTest` (the text fonts are derived from the 26.3 client jar)
 * and copied here verbatim, pinned by size and SHA-256. The lobby addresses these exact font ids
 * and codepoints, so the bytes must not drift. The sprite PNGs are platform artwork under
 * `art/platform/menu/` and are pinned in [ProductGraph].
 */
internal object MenuPack {
    private const val RESOURCE_ROOT = "menu-pack/"

    /**
     * Vanilla `gui` core shaders that discard the 1px white focus outline a dialog body draws
     * through the custom-drawn menus. They are vanilla overrides, so they are claimed explicitly.
     */
    val vanillaClaims: Set<VanillaPathClaim> =
        setOf("assets/minecraft/shaders/core/gui.fsh", "assets/minecraft/shaders/core/gui.vsh")
            .map { VanillaPathClaim(PackPath.of(it)) }
            .toSet()

    fun entries(): List<PackEntry> =
        FILES.map { (path, expected) ->
            val bytes =
                MenuPack::class.java.getResourceAsStream(RESOURCE_ROOT + path)?.use {
                    it.readAllBytes()
                } ?: throw java.io.IOException("Missing menu pack resource: $path")
            val sha256 =
                MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") {
                    "%02x".format(it)
                }
            if (bytes.size.toLong() != expected.first || sha256 != expected.second) {
                throw java.io.IOException("Menu pack resource hash mismatch: $path")
            }
            PackEntry.bytes(path, bytes)
        }

    private val FILES: Map<String, Pair<Long, String>> =
        linkedMapOf(
            "assets/grounds/font/menu/title.json" to
                (1_504L to "1be154bf46c2532cf33c58ac5f80e48c96380263403f6454e039233e5135620b"),
            "assets/grounds/font/menu/space.json" to
                (433L to "376ee38fb6e43bd2f193d221272ea5b2235018b1eff0a45c48c5db4e815d1d7a"),
            "assets/grounds/font/menu/art.json" to
